<script setup>
import { ref, computed, nextTick, onMounted, onBeforeUnmount } from 'vue'
import FlowIcon from './components/FlowIcon.vue'
import { CLUSTER_LABEL, SOCIAL_URL, TOKEN_EXPLORER_URL, TOKEN_MINT, TOKEN_SYMBOL } from './config'
import { useWallet } from './composables/useWallet'

const { connected, account, shortAccount, balance, tokenBalance, walletCluster, correctNetwork, isConnecting, isRefreshing, walletError, tokenError, tokenNotice, tokenConfigured, connectWallet, disconnect, refreshBalances } = useWallet()
const pages = ['Overview', 'Pools', 'Positions', 'Governance']
const labels = { Overview: 'Desk', Pools: 'Markets', Positions: 'Book', Governance: 'Protocol' }
const icons = { Overview: 'activity', Pools: 'layers', Positions: 'portfolio', Governance: 'community' }
const pools = [
  { id: 'orl-sol', name: 'ORL / SOL', token: 'ORL', profile: 'Core', apr: 18.4, tvl: 2.84, volume: 184.2, fee: '0.30%', color: 'mint', symbols: ['O', 'S'], model: 'Balanced liquidity' },
  { id: 'sol-usdc', name: 'SOL / USDC', token: 'SOL', profile: 'Stable', apr: 9.8, tvl: 14.2, volume: 902.6, fee: '0.05%', color: 'blue', symbols: ['S', '$'], model: 'Stable pair liquidity' },
  { id: 'orl-usdc', name: 'ORL / USDC', token: 'ORL', profile: 'Experimental', apr: 31.6, tvl: .92, volume: 74.8, fee: '1.00%', color: 'coral', symbols: ['O', '$'], model: 'Variable liquidity' },
]
const activePage = ref('Overview'), search = ref(''), filter = ref('All pools'), sort = ref('featured')
const filteredPools = computed(() => { const query = search.value.trim().toLowerCase(); const rows = pools.filter((pool) => (filter.value === 'All pools' || pool.profile === filter.value) && `${pool.name} ${pool.profile}`.toLowerCase().includes(query)); if (sort.value === 'apr') rows.sort((a, b) => b.apr - a.apr); if (sort.value === 'tvl') rows.sort((a, b) => b.tvl - a.tvl); return rows })
const selectedPoolId = ref(pools[0].id), selectedPool = computed(() => pools.find((pool) => pool.id === selectedPoolId.value) || pools[0]), secondaryToken = computed(() => selectedPool.value.name.split(' / ')[1])
const allocation = ref(50), allocationLabel = computed(() => `${allocation.value}% ${selectedPool.value.token} / ${100 - allocation.value}% ${secondaryToken.value}`)
const positions = ref([]), storageKey = 'solana.preview-positions.v1'
const modal = ref(''), previewStep = ref(1), previewAmount = ref(''), reviewedAmount = ref(''), amountError = ref(''), acknowledged = ref(false), dialog = ref(null), previewInput = ref(null), toast = ref('')
let previousFocus = null, toastTimer
const walletStatus = computed(() => { if (!connected.value) return 'Local previews work without a wallet.'; if (correctNetwork.value === false) return `Wallet reports Solana ${walletCluster.value}; reads are paused.`; return `Wallet reports Solana ${walletCluster.value}; balances are read-only.` })
function notify(value) { clearTimeout(toastTimer); toast.value = value; toastTimer = setTimeout(() => { toast.value = '' }, 4200) }
function readRoute() { const hash = window.location.hash.slice(1).toLowerCase(); activePage.value = hash === 'staking' ? 'Positions' : pages.find((page) => page.toLowerCase() === hash) || 'Overview'; document.title = `${labels[activePage.value]} | Dravora` }
function goTo(page) { closeModal(); activePage.value = page; window.location.hash = page.toLowerCase(); window.scrollTo({ top: 0, behavior: 'instant' }); nextTick(() => document.getElementById('main-content')?.focus({ preventScroll: true })) }
function openModal(type) { if (modal.value) return; previousFocus = document.activeElement; modal.value = type; document.body.style.overflow = 'hidden'; nextTick(() => { dialog.value?.showModal(); if (type === 'pool') previewInput.value?.focus() }) }
function closeModal() { if (dialog.value?.open) dialog.value.close(); else modal.value = '' }
function onDialogClose() { document.body.style.overflow = ''; modal.value = ''; if (previousFocus?.isConnected) previousFocus.focus({ preventScroll: true }) }
function onBackdrop(event) { if (event.target !== dialog.value) return; const rect = dialog.value.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) closeModal() }
function selectPool(pool) { selectedPoolId.value = pool.id; allocation.value = pool.id === 'sol-usdc' ? 70 : pool.id === 'orl-usdc' ? 35 : 50 }
function openPool(pool) { selectPool(pool); previewStep.value = 1; previewAmount.value = ''; reviewedAmount.value = ''; amountError.value = ''; acknowledged.value = false; openModal('pool') }
function validAmount(value) { return typeof value === 'string' && /^(?:\d+(?:\.\d{1,6})?|\.\d{1,6})$/.test(value.trim()) && Number(value) > 0 && Number(value) <= 1000000 }
function reviewPreview() { if (!validAmount(previewAmount.value)) { amountError.value = 'Enter an amount above 0 with up to 6 decimal places.'; previewInput.value?.focus(); return }; amountError.value = ''; reviewedAmount.value = String(Number(previewAmount.value)); previewStep.value = 2 }
function loadPositions() { try { const saved = JSON.parse(sessionStorage.getItem(storageKey) || '[]'); if (Array.isArray(saved)) positions.value = saved.filter((position) => position && pools.some((pool) => pool.id === position.poolId) && validAmount(String(position.amount))).slice(0, 100) } catch { positions.value = [] } }
function persistPositions() { try { sessionStorage.setItem(storageKey, JSON.stringify(positions.value)) } catch { notify('Session storage is unavailable; this preview lasts until refresh.') } }
function savePreview() { if (!acknowledged.value) return; positions.value.unshift({ id: crypto.randomUUID?.() || `preview-${Date.now()}`, poolId: selectedPool.value.id, amount: reviewedAmount.value, allocation: allocation.value, createdAt: Date.now() }); persistPositions(); goTo('Positions'); notify('Preview saved locally. No transaction was sent.') }
function removePosition(item) { positions.value = positions.value.filter((position) => position.id !== item.id); persistPositions(); notify('Preview removed from this session.') }
function poolFor(item) { return pools.find((pool) => pool.id === item.poolId) || pools[0] }
function displayDate(value) { return new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) }
function displayAmount(value) { return Number(value).toLocaleString('en-US', { maximumFractionDigits: 6 }) }
function resetFilters() { filter.value = 'All pools'; search.value = ''; sort.value = 'featured' }
async function connect() { if (await connectWallet()) notify('Solana wallet connected.') }
async function copyAddress() { if (!account.value) return; try { await navigator.clipboard.writeText(account.value); notify('Wallet address copied.') } catch { notify('Copy failed. Select the address and copy it manually.') } }
onMounted(() => { readRoute(); loadPositions(); window.addEventListener('hashchange', readRoute) })
onBeforeUnmount(() => { window.removeEventListener('hashchange', readRoute); clearTimeout(toastTimer) })
</script>

<template>
  <div class="app-shell">
    <a class="skip-link" href="#main-content" @click.prevent="document.getElementById('main-content')?.focus()">Skip to content</a>
    <header class="site-header"><a class="brand" href="#overview" aria-label="Dravora home" @click.prevent="goTo('Overview')"><img src="/dravora-mark.svg" alt="" width="34" height="34"><span>dravora</span></a><div class="market-tape"><span class="network-pill"><i></i>{{ CLUSTER_LABEL }}</span><span>ORL / SOL <b>18.4% APR</b></span><span>SOL / USDC <b>9.8% APR</b></span><span>ORL / USDC <b>31.6% APR</b></span></div><div class="header-actions"><a v-if="SOCIAL_URL" class="round-action" :href="SOCIAL_URL" target="_blank" rel="noopener noreferrer" aria-label="Open Dravora on X">X</a><button class="wallet-button" @click="openModal('wallet')"><FlowIcon name="wallet"/><span>{{ connected ? shortAccount : 'Connect wallet' }}</span></button></div></header>
    <div class="app-layout"><aside class="side-rail"><p class="rail-label">DRAVORA TERMINAL</p><nav aria-label="Main navigation"><a v-for="page in pages" :key="page" :href="'#' + page.toLowerCase()" :class="{ active: activePage === page }" :aria-current="activePage === page ? 'page' : undefined" @click.prevent="goTo(page)"><FlowIcon :name="icons[page]"/><span>{{ labels[page] }}</span><b v-if="page === 'Positions' && positions.length">{{ positions.length }}</b></a></nav><div class="rail-note"><span class="live-dot"></span><div><strong>Read-only mode</strong><small>Practice routes only</small></div></div><div class="rail-footer"><span>ORL</span><small>Classic SPL mint</small></div></aside>
      <main id="main-content" tabindex="-1" class="main-content"><div class="page-bar"><div><span class="crumb">DRAVORA / {{ CLUSTER_LABEL }}</span><h1>{{ activePage === 'Overview' ? 'Move with intent' : labels[activePage] }}</h1></div><div class="page-status"><span class="status-chip"><i></i> Demo data</span><button class="guide-button" aria-label="Open guide" @click="openModal('docs')"><FlowIcon name="book"/></button></div></div>
        <section v-if="activePage === 'Overview'" class="overview-view"><div class="hero-strip"><div><span class="eyebrow">SOLANA FLOW DESK</span><h2>Read the market.<br><em>Choose your move.</em></h2><p>Compare illustrative routes, tune a split, and keep a local practice position before any program is deployed.</p><div class="hero-actions"><button class="primary-button" @click="goTo('Pools')">Open markets <FlowIcon name="arrow"/></button><button class="text-button" @click="openModal('docs')">How it works <FlowIcon name="book"/></button></div></div><div class="hero-orbit" aria-hidden="true"><div class="orbit-grid"></div><span>ORL</span><i></i><span>SOL</span><b>DRVR</b></div></div><div class="stats-row"><div><span>Tracked routes</span><strong>{{ pools.length }}</strong><small>sample pairs</small></div><div><span>Combined TVL</span><strong>$18.0M</strong><small>illustrative</small></div><div><span>24h volume</span><strong>$1.16B</strong><small>illustrative</small></div><div class="positive"><span>Highest APR</span><strong>31.6%</strong><small>ORL / USDC</small></div></div><div class="trade-grid"><section class="route-panel"><div class="section-heading"><div><span class="eyebrow">MARKETS</span><h2>Choose a route</h2></div><button class="link-button" @click="goTo('Pools')">All markets <FlowIcon name="arrow"/></button></div><div class="filter-line"><div class="segmented"><button v-for="option in ['All pools','Core','Stable','Experimental']" :key="option" :class="{ selected: filter === option }" @click="filter = option">{{ option }}</button></div><label class="search-box"><FlowIcon name="search"/><input v-model="search" type="search" placeholder="Search pairs" aria-label="Search pool routes"></label></div><div class="route-table"><button v-for="pool in filteredPools" :key="pool.id" class="route-item" :class="{ selected: selectedPool.id === pool.id }" @click="selectPool(pool)"><span :class="['coin-stack', pool.color]"><i>{{ pool.symbols[0] }}</i><i>{{ pool.symbols[1] }}</i></span><span class="pair-copy"><strong>{{ pool.name }}</strong><small>{{ pool.profile }} · {{ pool.fee }} fee</small></span><span><small>APR</small><b>{{ pool.apr }}%</b></span><span><small>TVL</small><b>${{ pool.tvl }}M</b></span><FlowIcon name="chevron"/></button><div v-if="!filteredPools.length" class="empty-inline">No matching routes. <button class="link-button" @click="resetFilters">Reset</button></div></div><div class="selected-route"><div class="selected-route-head"><div><span class="eyebrow">SELECTED ROUTE</span><h3>{{ selectedPool.name }}</h3></div><span class="route-badge">{{ selectedPool.profile }}</span></div><div class="sparkline" aria-hidden="true"><i v-for="n in 30" :key="n" :style="{ height: (20 + ((n * 19 + selectedPool.apr * 4) % 68)) + '%' }"></i><b>{{ selectedPool.apr }}% APR</b></div><div class="route-facts"><span><small>Pool model</small><strong>{{ selectedPool.model }}</strong></span><span><small>Fee tier</small><strong>{{ selectedPool.fee }}</strong></span><span><small>Data state</small><strong>Illustrative</strong></span></div></div></section><aside class="action-panel"><div class="section-heading"><div><span class="eyebrow">POSITION BUILDER</span><h2>Shape a mix</h2></div><span class="local-badge">LOCAL</span></div><div class="pair-chip"><span :class="['coin-stack large', selectedPool.color]"><i>{{ selectedPool.symbols[0] }}</i><i>{{ selectedPool.symbols[1] }}</i></span><div><strong>{{ selectedPool.name }}</strong><small>{{ selectedPool.model }}</small></div><button class="icon-button" aria-label="Change route" @click="goTo('Pools')"><FlowIcon name="chevron"/></button></div><div class="mix-card"><div class="mix-title"><span>Allocation</span><b>{{ allocationLabel }}</b></div><div class="mix-wheel" :style="{ '--mix': allocation + '%' }"><strong>{{ allocation }}%</strong><small>{{ selectedPool.token }}</small></div><input v-model.number="allocation" aria-label="Allocation split" type="range" min="10" max="90" step="5"><div class="mix-legend"><span><i class="dot mint"></i>{{ selectedPool.token }} <b>{{ allocation }}%</b></span><span><i class="dot coral"></i>{{ secondaryToken }} <b>{{ 100 - allocation }}%</b></span></div></div><div class="quote-row"><span><small>Demo APR</small><b>{{ selectedPool.apr }}%</b></span><span><small>Demo TVL</small><b>${{ selectedPool.tvl }}M</b></span><span><small>Fee</small><b>{{ selectedPool.fee }}</b></span></div><button class="primary-button" @click="openPool(selectedPool)">Preview position <FlowIcon name="arrow"/></button><p class="action-note"><FlowIcon name="shield"/> No deposit or signature</p></aside></div><div class="disclosure"><FlowIcon name="info"/><span>Pool figures are fictional interface fixtures. Wallet access is optional and reads SOL plus {{ TOKEN_SYMBOL }} only from {{ CLUSTER_LABEL }}.</span><button class="link-button" @click="openModal('wallet')">Wallet details <FlowIcon name="arrow"/></button></div></section>
        <section v-else-if="activePage === 'Pools'" class="page-view"><div class="view-heading"><div><span class="eyebrow">ROUTE DISCOVERY</span><h2>Market routes</h2><p>Scan the pairs, then open a local preview.</p></div><span class="count-badge">{{ filteredPools.length }} routes</span></div><div class="pool-toolbar"><div class="segmented"><button v-for="option in ['All pools','Core','Stable','Experimental']" :key="option" :class="{ selected: filter === option }" @click="filter = option">{{ option }}</button></div><label class="search-box"><FlowIcon name="search"/><input v-model="search" type="search" placeholder="Search pairs" aria-label="Search pools"></label><select v-model="sort" aria-label="Sort pools"><option value="featured">Featured</option><option value="apr">Demo APR</option><option value="tvl">Demo TVL</option></select></div><div class="pool-grid"><article v-for="pool in filteredPools" :key="pool.id" class="pool-card" :class="[pool.color, { selected: selectedPool.id === pool.id }]" @click="selectPool(pool)"><div class="pool-card-top"><span :class="['coin-stack', pool.color]"><i>{{ pool.symbols[0] }}</i><i>{{ pool.symbols[1] }}</i></span><span class="route-badge">{{ pool.profile }}</span></div><h3>{{ pool.name }}</h3><p>{{ pool.model }} · {{ pool.fee }} fee</p><div class="mini-chart"><i v-for="n in 18" :key="n" :style="{ height: (25 + ((n * 17 + pool.apr * 3) % 65)) + '%' }"></i></div><div class="card-metrics"><span><small>Demo APR</small><b>{{ pool.apr }}%</b></span><span><small>Demo TVL</small><b>${{ pool.tvl }}M</b></span><span><small>24h vol</small><b>${{ pool.volume }}M</b></span></div><button class="secondary-button" @click.stop="openPool(pool)">Preview route <FlowIcon name="arrow"/></button></article></div><div v-if="!filteredPools.length" class="empty-state"><FlowIcon name="search"/><h3>No routes found</h3><p>Try another pair or reset the filters.</p><button class="secondary-button" @click="resetFilters">Reset filters</button></div></section>
        <section v-else-if="activePage === 'Positions'" class="page-view"><div class="view-heading"><div><span class="eyebrow">LOCAL LEDGER</span><h2>Saved positions</h2><p>Session previews stay in this browser tab.</p></div><button class="primary-button" @click="goTo('Pools')"><FlowIcon name="plus"/> New preview</button></div><div class="ledger-summary"><span class="summary-icon"><FlowIcon name="portfolio"/></span><div><small>Saved previews</small><strong>{{ String(positions.length).padStart(2, '0') }}</strong></div><span class="local-badge">SESSION ONLY</span></div><div v-if="!positions.length" class="empty-state"><span class="empty-icon"><FlowIcon name="layers"/></span><h3>No saved previews yet</h3><p>Select a route, set an amount and save it for this session.</p><button class="primary-button" @click="goTo('Pools')">Open route board <FlowIcon name="arrow"/></button></div><div v-else class="position-list"><div class="position-list-head"><span>Route / created</span><span>Amount</span><span>Mix</span><span>Status</span><span></span></div><article v-for="position in positions" :key="position.id" class="position-row"><div class="position-name"><span :class="['coin-single', poolFor(position).color]">{{ poolFor(position).symbols[0] }}</span><div><strong>{{ poolFor(position).name }}</strong><small>{{ poolFor(position).profile }} · {{ displayDate(position.createdAt) }}</small></div></div><b>{{ displayAmount(position.amount) }} <small>{{ poolFor(position).token }}</small></b><b>{{ position.allocation || 50 }} / {{ 100 - (position.allocation || 50) }}</b><span class="preview-status"><i></i> Preview</span><button class="icon-button" :aria-label="'Remove ' + poolFor(position).name + ' preview'" @click="removePosition(position)"><FlowIcon name="trash"/></button></article></div><p class="disclosure centered"><FlowIcon name="shield"/> Simulation only: no deposits, fees or accrued returns.</p></section>
        <section v-else class="page-view"><div class="view-heading"><div><span class="eyebrow">PROTOCOL STATUS</span><h2>Protocol</h2><p>Dravora keeps this release focused on research and local practice.</p></div><span class="count-badge muted">Coming later</span></div><div class="protocol-grid"><section class="protocol-card"><div class="protocol-mark"><FlowIcon name="community"/></div><span class="eyebrow">TOKEN + PROGRAM</span><h3>{{ tokenConfigured ? 'ORL mint configured.' : 'Mint pending.' }}<br>Governance paused.</h3><p>{{ tokenConfigured ? 'The ORL classic SPL Token mint is deployed on Solana Testnet. Pool and voting programs are not deployed.' : 'No Solana token mint, pool program, or voting account is configured in this workspace.' }}</p><div class="protocol-status"><i></i>{{ tokenConfigured ? 'ORL mint on ' + CLUSTER_LABEL : 'Waiting for deployment inputs' }}</div><p v-if="tokenConfigured" class="explorer-link"><a :href="TOKEN_EXPLORER_URL" target="_blank" rel="noopener noreferrer">View ORL mint on Explorer <FlowIcon name="external"/></a></p></section><section class="roadmap-card"><div class="section-heading"><div><span class="eyebrow">CAPABILITY MAP</span><h3>What works today</h3></div></div><ol><li><span class="road-node"><FlowIcon name="check"/></span><div><span class="route-badge success">AVAILABLE</span><h4>Compare and simulate</h4><p>Browse illustrative routes and save local previews without a wallet.</p><button class="link-button" @click="goTo('Pools')">Open route board <FlowIcon name="arrow"/></button></div></li><li><span class="road-node"><FlowIcon name="check"/></span><div><span class="route-badge info">OPTIONAL</span><h4>Read a Solana wallet</h4><p>Connect an injected wallet to read native SOL and ORL balances from the configured RPC.</p><button class="link-button" @click="openModal('wallet')">Manage wallet <FlowIcon name="arrow"/></button></div></li><li class="future"><span class="road-node"><FlowIcon name="clock"/></span><div><span class="route-badge">WAITING</span><h4>Pools, swaps, governance</h4><p>These actions stay disabled until their programs and verified data source are deployed.</p></div></li></ol></section></div></section>
      </main>
    </div>
    <footer class="site-footer"><span><b>DRAVORA</b> / Move with intent.</span><span>Solana Testnet · ORL classic SPL · read-only</span><a v-if="SOCIAL_URL" class="link-button" :href="SOCIAL_URL" target="_blank" rel="noopener noreferrer">X <FlowIcon name="external"/></a></footer>
    <nav class="mobile-nav" aria-label="Mobile navigation"><a v-for="page in pages" :key="page" :href="'#' + page.toLowerCase()" :class="{ active: activePage === page }" @click.prevent="goTo(page)"><FlowIcon :name="icons[page]"/><span>{{ labels[page] }}</span><b v-if="page === 'Positions' && positions.length">{{ positions.length }}</b></a></nav>
    <dialog ref="dialog" class="app-dialog" @close="onDialogClose" @click="onBackdrop"><div v-if="modal === 'pool'" class="dialog-body"><button class="dialog-close icon-button" aria-label="Close preview" @click="closeModal"><FlowIcon name="close"/></button><div class="dialog-kicker"><span class="route-badge">LOCAL PREVIEW</span><span>{{ previewStep }} / 2</span></div><template v-if="previewStep === 1"><h2>Build a {{ selectedPool.name }} position</h2><p class="dialog-lead">No wallet signature or asset movement is possible here.</p><label class="field-label" for="preview-amount">Practice amount</label><div class="amount-input"><input id="preview-amount" ref="previewInput" v-model="previewAmount" inputmode="decimal" placeholder="0.00" @keydown.enter.prevent="reviewPreview"><span>{{ selectedPool.token }}</span></div><p v-if="amountError" class="form-error" role="alert">{{ amountError }}</p><div class="quick-amounts"><button v-for="amount in ['25', '100', '250']" :key="amount" type="button" @click="previewAmount = amount">{{ amount }} {{ selectedPool.token }}</button></div><div class="dialog-summary"><span>Route <b>{{ selectedPool.name }}</b></span><span>Mix <b>{{ allocationLabel }}</b></span><span>Demo APR <b class="positive-text">{{ selectedPool.apr }}%</b></span></div><button class="primary-button full" @click="reviewPreview">Review position <FlowIcon name="arrow"/></button></template><template v-else><h2>Review before saving</h2><p class="dialog-lead">The position will be stored in this browser tab only.</p><div class="review-amount"><small>Practice amount</small><strong>{{ displayAmount(reviewedAmount) }} {{ selectedPool.token }}</strong></div><div class="dialog-summary"><span>Route <b>{{ selectedPool.name }}</b></span><span>Allocation <b>{{ allocationLabel }}</b></span><span>State <b>Simulation</b></span></div><label class="check-label"><input v-model="acknowledged" type="checkbox"> <span>I understand this preview does not deposit funds or execute a swap.</span></label><button class="primary-button full" :disabled="!acknowledged" @click="savePreview">Save local preview <FlowIcon name="check"/></button><button class="back-button" @click="previewStep = 1">Back to amount</button></template></div><div v-else-if="modal === 'wallet'" class="dialog-body"><button class="dialog-close icon-button" aria-label="Close wallet" @click="closeModal"><FlowIcon name="close"/></button><div class="dialog-kicker"><span class="route-badge">WALLET READER</span><span>{{ CLUSTER_LABEL }}</span></div><h2>{{ connected ? 'Wallet connected' : 'Connect to read balances' }}</h2><p class="dialog-lead">Dravora reads balances from an injected Solana wallet and never requests a signature for this demo.</p><div class="wallet-card"><FlowIcon name="wallet"/><div><strong>{{ connected ? shortAccount : 'No wallet connected' }}</strong><small>{{ walletStatus }}</small></div><i :class="{ connected }"></i></div><button v-if="connected" class="wallet-address" @click="copyAddress">{{ account }}</button><div v-if="connected" class="balance-grid"><span><small>SOL balance</small><b>{{ isRefreshing ? 'Refreshing...' : balance ?? '—' }}</b></span><span><small>{{ TOKEN_SYMBOL }} balance</small><b>{{ tokenBalance ?? '—' }}</b></span></div><p v-if="walletError" class="form-error" role="alert">{{ walletError }}</p><p v-if="tokenError || tokenNotice" class="token-notice">{{ tokenError || tokenNotice }}</p><div class="dialog-actions"><button v-if="!connected" class="primary-button full" :disabled="isConnecting" @click="connect">{{ isConnecting ? 'Connecting...' : 'Connect wallet' }} <FlowIcon name="wallet"/></button><template v-else><button class="secondary-button" @click="refreshBalances"><FlowIcon name="refresh"/> Refresh</button><button class="secondary-button" @click="disconnect">Disconnect</button></template></div><div v-if="tokenConfigured" class="mint-note"><strong>ORL mint configured</strong><small>{{ TOKEN_MINT }}</small><a :href="TOKEN_EXPLORER_URL" target="_blank" rel="noopener noreferrer">Open Explorer <FlowIcon name="external"/></a></div></div><div v-else class="dialog-body"><button class="dialog-close icon-button" aria-label="Close guide" @click="closeModal"><FlowIcon name="close"/></button><div class="dialog-kicker"><span class="route-badge">QUICK GUIDE</span><span>01—03</span></div><h2>Read the route first.</h2><p class="dialog-lead">Dravora is a Solana Testnet interface for comparing sample pools and saving local practice positions.</p><div class="guide-list"><div><b>01</b><p><strong>Pick a pair.</strong> Route figures are illustrative and marked as demo data.</p></div><div><b>02</b><p><strong>Set a mix.</strong> Try a practice amount and review the split.</p></div><div><b>03</b><p><strong>Save locally.</strong> No deposit, swap, governance or live pool program is available.</p></div></div><button class="primary-button full" @click="closeModal">Got it <FlowIcon name="check"/></button></div></dialog>
    <div v-if="toast" class="toast" role="status"><FlowIcon name="check"/> {{ toast }}</div>
  </div>
</template>
